public final class NativeSpellsSmokeTest {
    private static int checks;
    private static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
    private static void same(Object a,Object b,String text){check(Objects.equals(a,b),text+": "+a+" != "+b);}
    private static void rejects(Runnable work,String text){try{work.run();throw new AssertionError(text);}catch(IllegalArgumentException|IllegalStateException expected){check(true,text);}}
    private static Spell spell(Spell.EffectType effect,Spell.TargetType target,int cost,int power,int level){var d=new DataCore();d.setName("Trial spell");d.setStat(DataLayout.SPELL_EFFECT_TYPE,effect.ordinal());d.setStat(DataLayout.SPELL_TARGET,target.ordinal());d.setStat(DataLayout.SPELL_MP_COST,cost);d.setStat(DataLayout.SPELL_POWER,power);d.setStat(DataLayout.SPELL_LEVEL_REQ,level);return new Spell(d);}
    private static NativeSpellBook book(Spell spell,Job... jobs){return new NativeSpellBook(List.of(new NativeSpellBook.Entry(1,spell,Set.of(jobs))));}
    private static Monster foe(int hp){return EncounterFactory.buildMonster("Spell foe",hp,1,40);}
    public static void main(String[] args)throws Exception{
        if(args.length>0){var app=new DiagnosticApplication(DiagnosticContent.load(Path.of(args[0])),()->{});app.loadNative(Path.of(args[1]));same(Job.PRIEST.getBitValue(),app.nativeCampaign().party().get(1).getJob(),"child retains caster job");same(7,app.nativeCampaign().party().get(1).runtime().mp(),"child retains spent MP");same(4,DiagnosticSpells.BOOK.available(app.nativeCampaign().party().get(1)).size(),"child recreates explicit spell permissions");System.out.println("NATIVE_SPELLS_CHILD PASS");return;}
        definitions();planning();resolution();screens();System.out.println("NATIVE_SPELLS checks="+checks+" PASS");
    }
    private static void definitions(){
        var c=DiagnosticSpells.freshCampaign();var w=c.party().get(0);var p=c.party().get(1);same(4,DiagnosticSpells.BOOK.available(w).size(),"wizard choices");same(4,DiagnosticSpells.BOOK.available(p).size(),"priest choices");same(0,DiagnosticSpells.BOOK.available(NativeProgressionScreen.freshCampaign().party().get(0)).size(),"fighter gets no invented spells");
        var trainee=new NativeCampaignV5(List.of(PlayerCreationV5.create("Trainee",0,Job.PRIEST,0,20,20,15,100,10)),0,2,List.of(new NativeCampaignV5.TrainingStep(Job.PRIEST,2,0,0,0,0,List.of())));
        var higher=book(spell(Spell.EffectType.HEAL,Spell.TargetType.SINGLE_ALLY,3,12,2),Job.PRIEST);
        same(0,higher.available(trainee.party().get(0)).size(),"level requirement excludes untrained caster");trainee.train(trainee.party().get(0));same(1,higher.available(trainee.party().get(0)).size(),"guild level unlocks supplied permission");check(trainee.party().get(0).learned().isEmpty(),"spell policy does not invent physical technique learning");
        var original=spell(Spell.EffectType.HEAL,Spell.TargetType.SINGLE_ALLY,3,12,1);var b=book(original,Job.PRIEST);original.getDataCore().setStat(DataLayout.SPELL_MP_COST,99);same(3,b.entry(1).spell().getMpCost(),"book detaches source definition");b.entry(1).spell().getDataCore().setStat(DataLayout.SPELL_MP_COST,99);same(3,b.entry(1).spell().getMpCost(),"book exposes detached tools record");same(1,b.idOf(b.entry(1).spell()),"stable book identity");rejects(()->b.entry(0),"unknown ID");rejects(()->b.idOf(original),"foreign spell identity");rejects(()->new NativeSpellBook(List.of(b.entry(1),b.entry(1))),"duplicate IDs");rejects(()->new NativeSpellBook.Entry(0,original,Set.of(Job.PRIEST)),"zero ID");rejects(()->book(original),"missing job policy");rejects(()->book(spell(Spell.EffectType.HEAL,Spell.TargetType.SINGLE_ENEMY,1,1,1),Job.PRIEST),"wrong target domain");rejects(()->book(spell(Spell.EffectType.BUFF,Spell.TargetType.ALL_ALLIES,1,1,1),Job.PRIEST),"unimplemented effect");rejects(()->book(spell(Spell.EffectType.HEAL,Spell.TargetType.ALL_ALLIES,1,1,0),Job.PRIEST),"zero level");var invalid=spell(Spell.EffectType.HEAL,Spell.TargetType.ALL_ALLIES,1,1,1);invalid.getDataCore().setStat(DataLayout.SPELL_TARGET,255);rejects(()->book(invalid,Job.PRIEST),"invalid raw enum cannot silently clamp");
    }
    private static void planning(){
        var c=DiagnosticSpells.freshCampaign();var w=c.party().get(0);var p=c.party().get(1);var a=foe(200);var b=foe(200);var battle=c.startBattle(List.of(a,b),m->10);w.runtime().damage(20);p.runtime().damage(10);
        battle.select(w,Action.PARRY,null);battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,null);same(w.runtime(),battle.rows().get(1).order().allyTarget(),"auto healer selects injured ally");same(10,p.runtime().mp(),"selection does not spend MP");same(80,w.runtime().hp(),"selection does not heal");check(battle.canConfirm(),"complete spell plan ready");
        battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,p);same(p.runtime(),battle.rows().get(1).order().allyTarget(),"explicit ally override");rejects(()->battle.selectSpell(w,DiagnosticSpells.BOOK,5,null,null),"wrong job denied");rejects(()->battle.selectSpell(p,book(spell(Spell.EffectType.HEAL,Spell.TargetType.SINGLE_ALLY,1,1,2),Job.PRIEST),1,null,null),"higher level denied");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,999,null,null),"unknown spell denied");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,5,a,null),"ally spell rejects enemy");rejects(()->battle.selectSpell(w,DiagnosticSpells.BOOK,1,null,p),"enemy spell rejects ally");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,7,null,p),"group spell rejects single ally");rejects(()->battle.selectSpell(w,DiagnosticSpells.BOOK,3,a,null),"group spell rejects rank selector");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,DiagnosticSpells.freshCampaign().party().get(0)),"foreign ally denied");rejects(()->battle.selectSpell(w,DiagnosticSpells.BOOK,1,foe(100),null),"foreign enemy denied");
        battle.selectSpell(w,DiagnosticSpells.BOOK,1,b,null);same(b,battle.rows().get(0).order().enemyTarget(),"explicit enemy override");b.applyDamage(200);check(!battle.canConfirm(),"defeated spell target needs review");rejects(battle::confirmRound,"stale enemy blocks whole round");same(10,p.runtime().mp(),"invalid round spends no other caster MP");battle.select(w,Action.PARRY,null);p.runtime().spendMp(8);same(CombatOrderPlannerV5.RowStatus.NEEDS_REVIEW,battle.rows().get(1).status(),"MP change marks review");rejects(battle::confirmRound,"MP change blocks whole plan");same(80,w.runtime().hp(),"blocked plan does not run");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,w),"insufficient MP selection denied");p.runtime().restoreMp(8);battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,w);w.runtime().damage(100);same(CombatOrderPlannerV5.RowStatus.NEEDS_REVIEW,battle.rows().get(1).status(),"dead ally needs review");rejects(battle::confirmRound,"dead ally blocks plan");rejects(()->battle.selectSpell(p,DiagnosticSpells.BOOK,5,null,w),"dead ally selection denied");rejects(()->battle.selectSpell(w,DiagnosticSpells.BOOK,1,a,null),"dead caster denied");
    }
    private static CombatRoundV5 round(List<PlayerRuntimeV5> party,List<Monster> enemies,java.util.function.ToIntFunction<Object> initiative,boolean hit){return new CombatRoundV5(party,enemies,Map.of(),Map.of(),initiative,(p,m)->true,(m,p)->hit,m->100,(p,m)->true,(p,m)->true,p->true);}
    private static void resolution(){
        var c=DiagnosticSpells.freshCampaign();var w=c.party().get(0);var p=c.party().get(1);w.runtime().damage(30);p.runtime().damage(10);var battle=c.startBattle(List.of(foe(40)),m->0);battle.select(w,Action.PARRY,null);battle.selectSpell(p,DiagnosticSpells.BOOK,7,null,null);var healed=battle.confirmRound();same(7,p.runtime().mp(),"group heal pays once");check(healed.events().stream().anyMatch(e -> e instanceof CombatEvent.SpellCast cast && cast.targetName().equals(w.getName()) && cast.magnitude() <= -12 && cast.magnitude() >= -14),"group heal restores first injured member before enemy turn");same(100,p.runtime().hp(),"group heal clamps second member");same(10,w.runtime().mp(),"defender pays no MP");
        w.runtime().setAsleep(true);battle.select(w,Action.PARRY,null);battle.selectSpell(p,DiagnosticSpells.BOOK,8,null,null);battle.confirmRound();check(!w.runtime().isAsleep(),"group awaken clears native status");same(4,p.runtime().mp(),"group awaken pays once");battle.selectSpell(w,DiagnosticSpells.BOOK,3,null,null);battle.select(p,Action.PARRY,null);battle.confirmRound();same(7,w.runtime().mp(),"damage spell pays once even if resisted");battle.selectSpell(w,DiagnosticSpells.BOOK,4,null,null);battle.confirmRound();same(4,w.runtime().mp(),"sleep spell pays once regardless of resistance");
        var a=new PlayerRuntimeV5(PlayerCreationV5.create("Target",0,Job.FIGHTER,0,20,5,0,20,0));var healer=new PlayerRuntimeV5(PlayerCreationV5.create("Healer",0,Job.PRIEST,0,20,10,0,100,10));a.damage(10);var enemy=foe(200);var heal=DiagnosticSpells.BOOK.entry(5).spell();var r=round(List.of(a,healer),List.of(enemy),o->o==enemy?30:10,true);r.runRound(List.of(CombatRoundV5.PlayerOrder.parry(a),CombatRoundV5.PlayerOrder.cast(healer,heal,null,a)));same(0,a.hp(),"earlier enemy defeats selected ally");same(10,healer.mp(),"no surviving selected target preserves MP");
        var asleep=new PlayerRuntimeV5(PlayerCreationV5.create("Sleeping",0,Job.PRIEST,0,20,20,0,100,10));asleep.setAsleep(true);var awake=new PlayerRuntimeV5(PlayerCreationV5.create("Awake",0,Job.FIGHTER,0,20,10,0,100,0));awake.damage(10);round(List.of(asleep,awake),List.of(foe(200)),o->20,false).runRound(List.of(CombatRoundV5.PlayerOrder.cast(asleep,heal,null,awake),CombatRoundV5.PlayerOrder.parry(awake)));same(10,asleep.mp(),"sleeping caster preserves MP");same(90,awake.hp(),"sleeping caster does not heal");
        var runner=new PlayerRuntimeV5(PlayerCreationV5.create("Runner",0,Job.FIGHTER,0,20,30,0,100,0));var caster=new PlayerRuntimeV5(PlayerCreationV5.create("Caster",0,Job.WIZARD,0,20,10,0,100,10));var target=foe(200);var escaped=round(List.of(runner,caster),List.of(target),o->o==runner?30:10,false).runRound(List.of(CombatRoundV5.PlayerOrder.run(runner),CombatRoundV5.PlayerOrder.cast(caster,DiagnosticSpells.BOOK.entry(3).spell(),null,null)));same(CombatOutcome.ESCAPED,escaped.outcome(),"earlier escape ends round");same(10,caster.mp(),"later spell after escape spends nothing");same(200,target.getHp(),"later spell after escape affects nothing");
    }
    private static void key(ScreenManager manager,int code){var canvas=new Canvas();manager.getActiveScreen().onKeyPressed(new KeyEvent(canvas,KeyEvent.KEY_PRESSED,0,0,code,KeyEvent.CHAR_UNDEFINED));manager.update(.2f);manager.update(.2f);manager.getActiveScreen().onKeyReleased(new KeyEvent(canvas,KeyEvent.KEY_RELEASED,0,0,code,KeyEvent.CHAR_UNDEFINED));}
    private static void render(ScreenManager manager)throws Exception{var image=new BufferedImage(GameCanvas.DESIGN_WIDTH,GameCanvas.DESIGN_HEIGHT,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{manager.render(g,image.getWidth(),image.getHeight());}finally{g.dispose();}check(image.getRGB(80,80)!=0xff000000,"spell screen renders");javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("java.io.tmpdir"),"native-spells-plan.png").toFile());}
    private static void screens()throws Exception{
        Path root=Files.createTempDirectory("native-spells-");try{var content=DiagnosticContent.exportAndLoad(DiagnosticContent.create(),root.resolve("content"));var app=new DiagnosticApplication(content,()->{});var legacy=app.session();var old=app.nativeCampaign();key(app.manager(),KeyEvent.VK_C);check(old!=app.nativeCampaign(),"C installs fresh caster owner");same(legacy,app.session(),"caster fixture preserves legacy comparison owner");var c=app.nativeCampaign();var w=c.party().get(0);var p=c.party().get(1);w.runtime().damage(30);p.runtime().damage(10);c.startBattle(List.of(foe(20),foe(20)),m->0,r->true);key(app.manager(),KeyEvent.VK_V);key(app.manager(),KeyEvent.VK_S);same(Spell.TargetType.SINGLE_ENEMY,c.activeBattle().rows().get(0).order().spell().getTargetType(),"S chooses wizard spell");key(app.manager(),KeyEvent.VK_T);same(c.activeBattle().enemies().get(1),c.activeBattle().rows().get(0).order().enemyTarget(),"T overrides spell enemy");key(app.manager(),KeyEvent.VK_D);key(app.manager(),KeyEvent.VK_DOWN);key(app.manager(),KeyEvent.VK_S);same(w.runtime(),c.activeBattle().rows().get(1).order().allyTarget(),"S chooses priest heal and automatic ally");key(app.manager(),KeyEvent.VK_Y);same(p.runtime(),c.activeBattle().rows().get(1).order().allyTarget(),"Y overrides spell ally");key(app.manager(),KeyEvent.VK_S);key(app.manager(),KeyEvent.VK_S);same(Spell.TargetType.ALL_ALLIES,c.activeBattle().rows().get(1).order().spell().getTargetType(),"S cycles to group heal");key(app.manager(),KeyEvent.VK_T);same(Spell.TargetType.ALL_ALLIES,c.activeBattle().rows().get(1).order().spell().getTargetType(),"T cannot narrow group heal");key(app.manager(),KeyEvent.VK_S);key(app.manager(),KeyEvent.VK_S);same(Spell.TargetType.SINGLE_ALLY,c.activeBattle().rows().get(1).order().spell().getTargetType(),"S wraps spell choices");key(app.manager(),KeyEvent.VK_Y);same(10,p.runtime().mp(),"cycling spell choices never spends MP");render(app.manager());key(app.manager(),KeyEvent.VK_ENTER);same(7,p.runtime().mp(),"UI confirms one cast");same(100,p.runtime().hp(),"UI heals selected ally");same(CombatOrderPlannerV5.RowStatus.NEEDS_ORDER,c.activeBattle().rows().get(1).status(),"spell requires fresh next-round order");int hp=w.runtime().hp();key(app.manager(),KeyEvent.VK_ENTER);same(hp,w.runtime().hp(),"unassigned spell row cannot silently run next round");key(app.manager(),KeyEvent.VK_S);key(app.manager(),KeyEvent.VK_D);same(7,p.runtime().mp(),"replacing spell with defend preserves MP");key(app.manager(),KeyEvent.VK_UP);key(app.manager(),KeyEvent.VK_F);key(app.manager(),KeyEvent.VK_ENTER);same(CombatOutcome.ESCAPED,c.activeBattle().outcome(),"reviewed escape ends fixture fight");key(app.manager(),KeyEvent.VK_ENTER);key(app.manager(),KeyEvent.VK_ESCAPE);same(GameState.WORLD_ROAM,app.manager().getActiveState(),"caster party returns to menu");var save=root.resolve("spells.pns");app.saveNative(save);app.loadNative(save);same(7,app.nativeCampaign().party().get(1).runtime().mp(),"spent MP persists");same(4,DiagnosticSpells.BOOK.available(app.nativeCampaign().party().get(1)).size(),"loaded job recreates fixture permissions");key(app.manager(),KeyEvent.VK_N);same(app.nativeCampaign(),app.nativeTraversal().session(),"exploration uses restored caster owner");
            var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"--enable-preview","-Djava.awt.headless=true","-cp",System.getProperty("java.class.path"),NativeSpellsSmokeTest.class.getName(),root.resolve("content").toString(),save.toString()).redirectErrorStream(true).start();check(child.waitFor(30,java.util.concurrent.TimeUnit.SECONDS),"restart child completes");var output=new String(child.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(child.exitValue()==0&&output.contains("NATIVE_SPELLS_CHILD PASS"),"fresh JVM retains spell result: "+output);
        }finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    }
}
